<?php
declare(strict_types=1);
namespace MyInvoice\Tests\Integration\Property\Funds;
use MyInvoice\Repository\Property\Funds\FundingRepository;
use MyInvoice\Service\Property\Funds\{FundingException,FundingRead,FundingProof,FundingUseGuard};
use MyInvoice\Service\Property\PropertyInput;
use MyInvoice\Tests\Support\FundingFixture;
use PHPUnit\Framework\TestCase;
final class FundingBoundaryTest extends TestCase
{
    use FundingFixture;
    use \MyInvoice\Tests\Support\SharedFixtureSavepointTrait;

    /** Firma s předpisy a účty fondů je pro všechny testy stejná; staví se jednou za třídu. */
    protected function setUp():void
    {
        $this->fundingConnect();$this->beginSharedFixtureTest($this->db->pdo());$this->f=$this->sharedFixture('funding-base',fn():array=>$this->fundingBase());
    }
    protected function tearDown():void {$this->endSharedFixtureTest($this->db->pdo());}
    private function reject(callable $work,string $code):void {try{$work();self::fail('Invalid funding operation accepted: '.$code);}catch(FundingException $e){self::assertSame('property_funding_'.$code,$e->errorCode);}}
    private function draw():array {$this->fundingOpening();$cost=$this->fundingCost('2026-03-01','549.900','90000.00');return $this->fundingDraw('2026-03-01','repair','9000000',$cost);}
    public function testCostCannotBeCoveredTwiceAndOldRevisionCannotWrite():void
    {
        $r=$this->draw();$owner=new FundingRepository($this->db);$preview=$owner->preview($this->f['supplier'],$r,$this->f['actor']);$this->fundingApply($r,'first');$before=$this->db->pdo()->query('SELECT COUNT(*) FROM property_funding_operations')->fetchColumn();$this->reject(fn()=>$owner->apply($this->f['supplier'],$r,$preview['preview_hash'],'stale',$this->f['actor']),'revision_conflict');$r['expected_revision']=1;$this->reject(fn()=>$owner->preview($this->f['supplier'],$r,$this->f['actor']),'capacity');self::assertSame($before,$this->db->pdo()->query('SELECT COUNT(*) FROM property_funding_operations')->fetchColumn());
    }
    public function testNegativeNativePrescriptionReducesSpendableBalance():void
    {
        $batch=$this->fundingIssue();$this->fundingReduceIssuedLong($batch);$cost=$this->fundingCost('2026-03-01','549.900','90000.00');$r=$this->fundingDraw('2026-03-01','repair','9000000',$cost,'issued');$read=(new FundingRead($this->db))->at($this->f['supplier'],null,'2026-03-01');self::assertTrue($read['matches']);self::assertSame('3000000',$read['totals']['955.100']);$this->reject(fn()=>(new FundingRepository($this->db))->preview($this->f['supplier'],$r,$this->f['actor']),'balance_capacity');
    }
    public function testFutureKeyAndForeignCommonPropertyCannotBeUsed():void
    {
        $r=$this->draw();$r['effective_at']='2026-03-01T08:00:00+01:00';$this->reject(fn()=>(new FundingRepository($this->db))->preview($this->f['supplier'],$r,$this->f['actor']),'key_date');unset($r['effective_at']);$r['ownership']='svj_owned';$this->expectException(\MyInvoice\Service\Accounting\AccountingFrameworkException::class);(new FundingRepository($this->db))->preview($this->f['supplier'],$r,$this->f['actor']);
    }
    public function testAdvanceCapacityAndUnitKeyAreEnforced():void
    {
        $this->fundingOpening();$cost=$this->fundingCost('2026-03-01','549.900','330000.00');$r=$this->fundingDraw('2026-03-01','repair','33000000',$cost);$owner=new FundingRepository($this->db);$this->reject(fn()=>$owner->preview($this->f['supplier'],$r,$this->f['actor']),'capacity');$r=$this->fundingDraw('2026-03-01','repair','9000000',$cost);$r['sources'][0]['amount_cents']=bcsub($r['sources'][0]['amount_cents'],'1',0);$this->reject(fn()=>$owner->preview($this->f['supplier'],$r,$this->f['actor']),'key_amount');
    }
    public function testCurrentProofRejectsNativeCostAndCoherentlyRehashedEffects():void
    {
        $r=$this->draw();$op=$this->fundingApply($r,'draw');$owner=new FundingRepository($this->db);$s=$this->f['supplier'];$pdo=$this->db->pdo();$pdo->exec('SAVEPOINT changed_cost');$pdo->prepare("UPDATE journal_entry_lines SET cost_center='SYNTHETIC-TAMPER' WHERE supplier_id=? AND id=?")->execute([$s,$r['cost_line_id']]);$this->reject(fn()=>$owner->operation($s,$op['id']),'source_changed');$pdo->exec('ROLLBACK TO SAVEPOINT changed_cost');
        $snapshot=$op['snapshot'];$snapshot['effects'][0]['amount_cents']=bcsub($snapshot['effects'][0]['amount_cents'],'1',0);$receipt=$op['receipt'];$receipt['effects'][0]['amount_cents']=$snapshot['effects'][0]['amount_cents'];$hash=PropertyInput::hash($snapshot);$requestHash=PropertyInput::hash(['request'=>$op['request'],'preview_hash'=>$hash,'token'=>$op['idempotency_key'],'actor'=>$this->f['actor']]);$pdo->prepare('UPDATE property_funding_effects SET amount_cents=? WHERE supplier_id=? AND id=?')->execute([$snapshot['effects'][0]['amount_cents'],$s,$receipt['effects'][0]['id']]);$pdo->prepare('UPDATE property_funding_operations SET snapshot_json=?,snapshot_hash=?,request_hash=?,receipt_json=?,receipt_hash=? WHERE supplier_id=? AND id=?')->execute([json_encode($snapshot),$hash,$requestHash,json_encode($receipt),PropertyInput::hash($receipt),$s,$op['id']]);$this->reject(fn()=>$owner->operation($s,$op['id']),'financial_reciprocity');
    }
    public static function counterpartMutations():array {return [['coverage_amount'],['coverage_currency'],['coverage_dimension'],['coverage_account'],['income_bank_account'],['income_bank_account_and_facts'],['payout_bank_amount']];}
    #[\PHPUnit\Framework\Attributes\DataProvider('counterpartMutations')]
    public function testCoherentlyRehashedNativeCounterpartMustStillMatchSources(string $mutation):void
    {
        $s=$this->f['supplier'];$pdo=$this->db->pdo();
        if(str_starts_with($mutation,'coverage_')){$op=$this->fundingApply($this->draw(),'draw');$index=1;}
        else{$r=$this->fundingRequest('income','2026-03-01','6000000')+['bank_id'=>$this->fundingBank('2026-03-01','60000.00'),'key'=>$this->fundingKey('2026-03-01')];$op=$this->fundingApply($r,'income');$index=0;if($mutation==='payout_bank_amount'){$lot=$op['receipt']['effects'][0];$r=$this->fundingRequest('payout','2026-03-02','100')+['bank_id'=>$this->fundingBank('2026-03-02','-1.00'),'recipient_id'=>$this->f['clients'][1],'recipient_account'=>'1000000005/0100','dispositions'=>[['source_id'=>$lot['id'],'amount_cents'=>'100','party_ids'=>$lot['parties']['members'],'evidence_ref'=>'Synthetic payout instruction']]];$op=$this->fundingApply($r,'payout');$index=1;}}
        $snapshot=$op['snapshot'];$line=&$snapshot['journal']['lines'][$index];$lineId=$op['receipt']['ledger']['lines'][$index]['id'];
        if(in_array($mutation,['coverage_amount','payout_bank_amount'],true)){$line['amount']='2.00';$pdo->prepare('UPDATE journal_entry_lines SET amount=? WHERE supplier_id=? AND id=?')->execute(['2.00',$s,$lineId]);}
        elseif($mutation==='coverage_currency'){$line['currency_code']='EUR';$line['amount_foreign']='2.00';$line['fx_rate']='1.000000';$pdo->prepare("UPDATE journal_entry_lines SET currency_code='EUR',amount_foreign=2,fx_rate=1 WHERE supplier_id=? AND id=?")->execute([$s,$lineId]);}
        elseif(str_starts_with($mutation,'income_bank_account')||$mutation==='coverage_account'){$code=$mutation==='coverage_account'?'649.200':'211';$q=$pdo->prepare('SELECT id FROM chart_of_accounts WHERE supplier_id=? AND account_code=?');$q->execute([$s,$code]);$account=(int)$q->fetchColumn();if($mutation==='income_bank_account_and_facts'){$snapshot['proofs']['bank']['money_account']=$code;$q=$pdo->prepare('SELECT id,account_code,account_type,is_active FROM chart_of_accounts WHERE supplier_id=? AND id=?');$q->execute([$s,$account]);$snapshot['proofs']['bank']['money_account_receipt']=$q->fetch(\PDO::FETCH_ASSOC);$snapshot['proofs']['bank']['source_etag']=\MyInvoice\Service\Property\Payments\Workflow\PaymentSourceEligibility::etag($snapshot['proofs']['bank']);}$line['account_code']=$code;$line['account_id']=$account;$pdo->prepare('UPDATE journal_entry_lines SET account_id=? WHERE supplier_id=? AND id=?')->execute([$account,$s,$lineId]);}
        else{$oldUnit=$op['receipt']['effects'][0]['unit_id'];$oldDims=(new \MyInvoice\Service\Property\Funds\FundingSourceProof($this->db))->dimensions($s,$oldUnit);$newDims=(new \MyInvoice\Service\Property\Funds\FundingSourceProof($this->db))->dimensions($s,$this->f['units']['G12']);$type=array_key_first($oldDims);$line['dimensions'][$type]=$newDims[$type];$pdo->prepare('UPDATE journal_entry_line_dimensions SET dimension_value_id=? WHERE supplier_id=? AND line_id=? AND dimension_type_id=?')->execute([$newDims[$type],$s,$lineId,$type]);}
        unset($line);$receipt=$op['receipt'];$receipt['ledger']=(new \MyInvoice\Service\Property\Payments\PaymentJournalProof($this->db))->current($s,$op['journal_entry_id']);$hash=PropertyInput::hash($snapshot);$requestHash=PropertyInput::hash(['request'=>$op['request'],'preview_hash'=>$hash,'token'=>$op['idempotency_key'],'actor'=>$this->f['actor']]);$pdo->prepare('UPDATE property_funding_operations SET snapshot_json=?,snapshot_hash=?,request_hash=?,receipt_json=?,receipt_hash=? WHERE supplier_id=? AND id=?')->execute([json_encode($snapshot),$hash,$requestHash,json_encode($receipt),PropertyInput::hash($receipt),$s,$op['id']]);try{(new FundingRepository($this->db))->operation($s,$op['id']);self::fail('Rehashed native counterpart accepted: '.$mutation);}catch(FundingException $e){self::assertStringStartsWith('property_funding_',$e->errorCode);}
    }
    public function testCoverageCarriesActualNativeFinancialContext():void
    {
        $r=$this->draw();$this->db->pdo()->prepare("UPDATE journal_entry_lines SET cost_center='SYNTHETIC-CONTEXT' WHERE supplier_id=? AND id=?")->execute([$this->f['supplier'],$r['cost_line_id']]);$op=$this->fundingApply($r,'financial-context');$cost=$op['snapshot']['proofs']['cost']['line'];$coverage=$op['receipt']['ledger']['lines'][1];self::assertSame('SYNTHETIC-CONTEXT',$coverage['cost_center']);foreach($cost['dimensions'] as $type=>$value)self::assertSame($value,$coverage['dimensions'][$type]);self::assertSame($op['id'],(new FundingRepository($this->db))->operation($this->f['supplier'],$op['id'])['id']);
    }
    public function testNativeHeaderCannotBeRetargetedWithRehashedReceipt():void
    {
        $r=$this->fundingRequest('income','2026-03-01','6000000')+['bank_id'=>$this->fundingBank('2026-03-01','60000.00'),'key'=>$this->fundingKey('2026-03-01')];$op=$this->fundingApply($r,'income');$s=$this->f['supplier'];$this->db->pdo()->prepare('UPDATE journal_entries SET source_id=source_id+1000000 WHERE supplier_id=? AND id=?')->execute([$s,$op['journal_entry_id']]);$receipt=$op['receipt'];$receipt['ledger']=(new \MyInvoice\Service\Property\Payments\PaymentJournalProof($this->db))->current($s,$op['journal_entry_id']);$this->db->pdo()->prepare('UPDATE property_funding_operations SET receipt_json=?,receipt_hash=? WHERE supplier_id=? AND id=?')->execute([json_encode($receipt),PropertyInput::hash($receipt),$s,$op['id']]);$this->reject(fn()=>(new FundingRepository($this->db))->operation($s,$op['id']),'journal_mismatch');
    }
    public function testRehashedClaimCannotAlterCapacity():void
    {
        $op=$this->fundingApply($this->draw(),'draw');$snapshot=$op['snapshot'];$receipt=$op['receipt'];$snapshot['claims'][0]['amount_cents']='1';$receipt['claims'][0]['amount_cents']='1';$hash=PropertyInput::hash($snapshot);$requestHash=PropertyInput::hash(['request'=>$op['request'],'preview_hash'=>$hash,'token'=>$op['idempotency_key'],'actor'=>$this->f['actor']]);$s=$this->f['supplier'];$claim=$snapshot['claims'][0];$this->db->pdo()->prepare('UPDATE property_funding_claims SET amount_cents=1 WHERE supplier_id=? AND operation_id=? AND source_kind=? AND source_id=? AND claim_role=?')->execute([$s,$op['id'],$claim['source_kind'],$claim['source_id'],$claim['claim_role']]);$this->db->pdo()->prepare('UPDATE property_funding_operations SET snapshot_json=?,snapshot_hash=?,request_hash=?,receipt_json=?,receipt_hash=? WHERE supplier_id=? AND id=?')->execute([json_encode($snapshot),$hash,$requestHash,json_encode($receipt),PropertyInput::hash($receipt),$s,$op['id']]);$this->reject(fn()=>(new FundingRepository($this->db))->operation($s,$op['id']),'claim_mismatch');
    }
    public function testNativeReversalRestoresBalanceAtItsOwnDateAndReleasesCapacity():void
    {
        $r=$this->draw();$op=$this->fundingApply($r,'draw');$reverse=$this->fundingRequest('reverse','2026-04-01');unset($reverse['amount_cents']);$reverse['operation_id']=$op['id'];$reversed=$this->fundingApply($reverse,'reverse');self::assertFalse((new FundingRepository($this->db))->operation($this->f['supplier'],$op['id'])['active']);self::assertSame($reversed['journal_entry_id'],(new \MyInvoice\Service\Property\Payments\PaymentJournalProof($this->db))->current($this->f['supplier'],$op['journal_entry_id'])['entry']['reversed_by']);$read=new FundingRead($this->db);$march=$read->at($this->f['supplier'],null,'2026-03-31');self::assertTrue($march['matches']);self::assertSame('21000000',$march['totals']['955.100']);$april=$read->at($this->f['supplier'],null,'2026-04-01');self::assertTrue($april['matches']);self::assertSame('30000000',$april['totals']['955.100']);$r['expected_revision']=2;$this->reject(fn()=>(new FundingRepository($this->db))->preview($this->f['supplier'],$r,$this->f['actor']),'chronology');$r['accounting_date']='2026-04-01';$r['key']=$this->fundingKey('2026-04-01');$this->fundingApply($r,'redraw');self::assertSame('21000000',$read->at($this->f['supplier'],null,'2026-04-01')['totals']['955.100']);
    }
    public function testUnregisteredLedgerCannotProduceFalseGreenRecon():void
    {
        $this->fundingOpening();$s=$this->f['supplier'];$this->container->get(\MyInvoice\Service\Accounting\PostingService::class)->postDocument($s,'manual',null,[['account_code'=>'221','side'=>'debit','amount'=>'7.00'],['account_code'=>'955.100','side'=>'credit','amount'=>'7.00']],['entry_date'=>'2026-02-01','posted_by'=>$this->f['actor']]);$read=(new FundingRead($this->db))->at($s,null,'2026-12-31');self::assertFalse($read['matches']);self::assertCount(1,$read['unregistered_line_ids']);
    }
    public function testIncomeRequiresHistoricalOwnerGroupsAndBankSingleUse():void
    {
        $s=$this->f['supplier'];$bank=$this->fundingBank('2026-03-01','60000.00');$r=$this->fundingRequest('income','2026-03-01','6000000')+['bank_id'=>$bank,'key'=>$this->fundingKey('2026-03-01')];$op=$this->fundingApply($r,'income');self::assertCount(14,$op['receipt']['effects']);$sjm=array_values(array_filter($op['receipt']['effects'],fn($e)=>$e['unit_id']===$this->f['units']['U01']));self::assertCount(1,$sjm);self::assertCount(2,$sjm[0]['parties']['members']);$this->reject(fn()=>FundingUseGuard::assertSourceUnclaimed($this->db,$s,'bank',$bank),'source_owned');
        $d=['source_id'=>$sjm[0]['id'],'amount_cents'=>'100','party_ids'=>[$this->f['clients'][18]],'evidence_ref'=>'Synthetic invalid substitute owner'];$r=$this->fundingRequest('transfer','2026-03-02','100')+['dispositions'=>[$d],'target'=>'long_term','purpose_ref'=>'Synthetic future repair','settlement_due_on'=>'2029-12-31'];$this->reject(fn()=>(new FundingRepository($this->db))->preview($s,$r,$this->f['actor']),'disposition_parties');$d['party_ids']=$sjm[0]['parties']['members'];$d['amount_cents']='540001';$r['dispositions']=[$d];$r['amount_cents']='540001';$this->reject(fn()=>(new FundingRepository($this->db))->preview($s,$r,$this->f['actor']),'capacity');
    }
    public function testExpiredProofCannotSurviveOwnerSavepointRollback():void
    {
        $r=$this->draw();$owner=new FundingRepository($this->db);$preview=$owner->preview($this->f['supplier'],$r,$this->f['actor']);$pdo=$this->db->pdo();$pdo->exec('SAVEPOINT before_pending');$r=$preview['plan']['request'];$plan=$preview['plan'];$pdo->prepare('INSERT INTO property_funding_operations(supplier_id,house_id,kind,accounting_date,effective_at,revision,request_json,request_hash,snapshot_json,snapshot_hash,idempotency_key,created_by,recorded_at) VALUES(?,?,?,?,?,1,?,?,?,?,?,?,UTC_TIMESTAMP(6))')->execute([$this->f['supplier'],$r['house_id'],'draw',$r['accounting_date'],\MyInvoice\Service\Property\PropertyInstant::sql($r['effective_at']),json_encode($r),PropertyInput::hash(['request'=>$r,'preview_hash'=>$preview['preview_hash'],'token'=>'pending','actor'=>$this->f['actor']]),json_encode($plan),$preview['preview_hash'],'pending',$this->f['actor']]);$id=(int)$pdo->lastInsertId();$proof=FundingProof::fromPending($this->db,$owner,$this->f['supplier'],$id);$proof->journal($this->db);$pdo->exec('ROLLBACK TO SAVEPOINT before_pending');$this->expectException(\LogicException::class);$proof->journal($this->db);
    }
    public function testFutureOwnershipRevisionDoesNotRetargetOriginalIncomeGroups():void
    {
        $r=$this->fundingRequest('income','2026-03-01','6000000')+['bank_id'=>$this->fundingBank('2026-03-01','60000.00'),'key'=>$this->fundingKey('2026-03-01')];$op=$this->fundingApply($r,'income');$state=$this->f['states']['U01'];$state['ownerships']=[['group_key'=>'NEW','kind'=>'single','share'=>['num'=>'1','den'=>'1'],'members'=>[$this->f['clients'][18]],'title_ref'=>'Synthetic April sale']];(new \MyInvoice\Repository\Property\PropertyRegistryRepository($this->db))->revise($this->f['supplier'],$this->f['units']['U01'],'unit',['expected_revision'=>1,'effective_from'=>'2026-04-01T00:00:00+02:00','effective_to'=>null,'status'=>'confirmed','state'=>$state,'reason'=>'Synthetic later ownership change','title_ref'=>'Synthetic sale deed','idempotency_key'=>'sale'],$this->f['actor']);$current=(new FundingRepository($this->db))->operation($this->f['supplier'],$op['id']);self::assertSame($op['receipt'],$current['receipt']);$sjm=array_values(array_filter($current['receipt']['effects'],fn($e)=>$e['unit_id']===$this->f['units']['U01']))[0];self::assertSame([$this->f['clients'][1],$this->f['clients'][2]],$sjm['parties']['members']);$r=$this->fundingRequest('transfer','2026-05-01','100')+['dispositions'=>[['source_id'=>$sjm['id'],'amount_cents'=>'100','party_ids'=>$sjm['parties']['members'],'evidence_ref'=>'Synthetic original owners consent after sale']],'target'=>'long_term','purpose_ref'=>'Synthetic roof repairs','settlement_due_on'=>'2029-12-31'];$this->fundingApply($r,'historical-disposition');self::assertTrue((new FundingRead($this->db))->at($this->f['supplier'],null,'2026-05-01')['matches']);
    }
    public function testKnowledgeCutoffUsesMicrosecondNativeReceiptTime():void
    {
        $this->fundingOpening();$r=$this->fundingRequest('income','2026-03-01','6000000')+['bank_id'=>$this->fundingBank('2026-03-01','60000.00'),'key'=>$this->fundingKey('2026-03-01')];$op=$this->fundingApply($r,'income');$before=(new \DateTimeImmutable($op['recorded_at'],new \DateTimeZone('UTC')))->modify('-1 microsecond')->format('Y-m-d\TH:i:s.u\Z');$after=(new \DateTimeImmutable($op['recorded_at'],new \DateTimeZone('UTC')))->modify('+1 microsecond')->format('Y-m-d\TH:i:s.u\Z');$read=new FundingRead($this->db);$past=$read->at($this->f['supplier'],null,'2026-12-31',$before);self::assertTrue($past['matches'],json_encode($past['differences']));self::assertArrayNotHasKey('379.920',$past['totals']);self::assertSame('30000000',$past['totals']['955.100']);$present=$read->at($this->f['supplier'],null,'2026-12-31',$after);self::assertTrue($present['matches']);self::assertSame('6000000',$present['totals']['379.920']);
    }
    public function testDirectNativeCoverageIsNotAvailableForAnotherDraw():void
    {
        $r=$this->draw();$s=$this->f['supplier'];$row=$this->db->pdo()->prepare('SELECT entry_id FROM journal_entry_lines WHERE supplier_id=? AND id=?');$row->execute([$s,$r['cost_line_id']]);$entry=(int)$row->fetchColumn();$q=$this->db->pdo()->prepare("UPDATE journal_entry_lines l JOIN chart_of_accounts c ON c.supplier_id=l.supplier_id AND c.account_code='649.100' SET l.account_id=c.id WHERE l.supplier_id=? AND l.entry_id=? AND l.side='credit'");$q->execute([$s,$entry]);$this->reject(fn()=>(new FundingRepository($this->db))->preview($s,$r,$this->f['actor']),'capacity');
    }
}
